                const target = this.workerActualWorkRootTarget(worker);
                rows.push(ApiWorkflow_1.serverTestRow({
                    id: worker.id,
                    host: target.host,
                    port: target.port,
                    user: target.user,
                    remotePath: target.remotePath,
                }, this.lastWorkerProbes[worker.id]));
