        let verifyIssues: any;
        let _verifyOk: boolean;
        if (showMessage) {
            verifyIssues = await this.verifyDeployedAgentRuntime(targets, manifest);
            _verifyOk = verifyIssues.fatal.length === 0 && verifyIssues.warnings.length === 0;
        } else {
            await sleep(800);
            const _verifyTimeoutMs = 30000;
            const _verifyIntervalMs = 800;
            const _verifyDeadline = Date.now() + (_verifyTimeoutMs - 800);
            verifyIssues = await this.verifyDeployedAgentRuntime(targets, manifest);
            _verifyOk = verifyIssues.fatal.length === 0 && verifyIssues.warnings.length === 0;
            while (!_verifyOk && Date.now() <= _verifyDeadline) {
                if (verifyIssues.fatal.length) break;
                if (Date.now() + _verifyIntervalMs > _verifyDeadline) break;
                await sleep(_verifyIntervalMs);
                verifyIssues = await this.verifyDeployedAgentRuntime(targets, manifest);
                _verifyOk = verifyIssues.fatal.length === 0 && verifyIssues.warnings.length === 0;
                if (_verifyOk) break;
            }
        }
        if (verifyIssues.fatal.length)
            throw new Error(`Agent runtime 部署校验失败：${verifyIssues.fatal.join("; ")}`);
        if (!_verifyOk && verifyIssues.warnings.length) {
            if (showMessage) void vscode.window.showWarningMessage(`Agent runtime 已部署，但部分目标未校验：${verifyIssues.warnings.join("；")}`);
            else console.warn(`[Agent runtime 已部署，但部分目标未校验（静默）] ${verifyIssues.warnings.join("；")}`);
        }
        // Reuse this deployment's complete SHA256/version verification instead of repeating all requests.
        const _shaDetails: string[] = _verifyOk
            ? targets.flatMap(target => ["cluster_agent.py", "cluster_scheduler.py"]
                .filter(name => (manifest as any).files?.[name] || (manifest as any).components?.[name === "cluster_agent.py" ? "hub_agent" : "cluster_scheduler"]?.sha256)
                .map(name => `${target.label}/${name}:sha256 ok`))
            : [...verifyIssues.fatal, ...verifyIssues.warnings];
        if (targets.some((target) => target.role === "hub"))
            this.lastProbe = undefined;
        for (const target of targets.filter((item) => item.role !== "hub"))
            delete this.lastWorkerProbes[target.id];
        this.lastFullEndpointProbeAt = 0;
