                    throw new Error("指标文件无法核验大小和 SHA256：" + file.remotePath);
                if (file.sha256 && file.sha256 !== evidence.sha256 || file.bytes != null && file.bytes !== evidence.size) throw new Error("指标文件身份已变化：" + file.remotePath);
