        if (allowFallback && !workers.some((worker) => worker.id === requested)) {
            if (workers[0]?.id) return workers[0].id;
        }
        if (!requested || !workers.some((worker) => worker.id === requested)) throw new Error(`未配置 tmux Worker：${requested || "-"}`);
